def count_pairs_of_connectable_servers(edges: list[list[int]], signal_speed: int) -> list[int]:
    n = len(edges) + 1
    adj = [[] for _ in range(n)]
    for a, b, w in edges:
        adj[a].append((b, w))
        adj[b].append((a, w))

    result = [0] * n
    for c in range(n):
        seen = 0      # qualifying servers in the branches already processed
        pairs = 0
        for start, weight in adj[c]:
            # Count servers in this branch whose distance from c is divisible.
            branch = 0
            stack = [(start, c, weight)]
            while stack:
                node, parent, dist = stack.pop()
                if dist % signal_speed == 0:
                    branch += 1
                for nxt, w in adj[node]:
                    if nxt != parent:
                        stack.append((nxt, node, dist + w))
            pairs += seen * branch
            seen += branch
        result[c] = pairs
    return result

def num_subarrays_with_sum(nums: list[int], goal: int) -> int:
    def at_most(limit: int) -> int:
        # Number of subarrays whose sum is <= limit.
        if limit < 0:
            return 0
        left = total = count = 0
        for right, x in enumerate(nums):
            total += x
            while total > limit:
                total -= nums[left]
                left += 1
            count += right - left + 1
        return count

    return at_most(goal) - at_most(goal - 1)

