def find_length(nums1: list[int], nums2: list[int]) -> int:
    MOD = (1 << 61) - 1
    BASE = 1000003

    def prefix_hashes(arr: list[int]) -> list[int]:
        h = [0] * (len(arr) + 1)
        for i, x in enumerate(arr):
            h[i + 1] = (h[i] * BASE + x + 1) % MOD
        return h

    n1, n2 = len(nums1), len(nums2)
    h1, h2 = prefix_hashes(nums1), prefix_hashes(nums2)
    power = [1] * (max(n1, n2) + 1)
    for i in range(1, len(power)):
        power[i] = power[i - 1] * BASE % MOD

    def has_common(length: int) -> bool:
        p = power[length]
        starts = {}
        for i in range(n1 - length + 1):
            key = (h1[i + length] - h1[i] * p) % MOD
            starts.setdefault(key, []).append(i)
        for j in range(n2 - length + 1):
            hits = starts.get((h2[j + length] - h2[j] * p) % MOD)
            if hits:
                window = nums2[j:j + length]
                # Confirm against collisions with a direct comparison.
                if any(nums1[i:i + length] == window for i in hits):
                    return True
        return False

    lo, hi = 0, min(n1, n2)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if has_common(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

