def longest_dup_substring(s: str) -> str:
    n = len(s)
    MOD = (1 << 61) - 1
    BASE = 911382323
    pre = [0] * (n + 1)
    power = [1] * (n + 1)
    for i, ch in enumerate(s):
        pre[i + 1] = (pre[i] * BASE + ord(ch)) % MOD
        power[i + 1] = power[i] * BASE % MOD

    def repeat_start(length: int) -> int:
        # Start index of a window of this length that also occurs earlier, or -1.
        p = power[length]
        first = {}
        for i in range(n - length + 1):
            h = (pre[i + length] - pre[i] * p) % MOD
            j = first.setdefault(h, i)
            if j != i and s[j:j + length] == s[i:i + length]:
                return i
        return -1

    lo, hi = 1, n - 1
    start, best = 0, 0
    while lo <= hi:
        mid = (lo + hi) // 2
        i = repeat_start(mid)
        if i >= 0:
            start, best = i, mid
            lo = mid + 1
        else:
            hi = mid - 1
    return s[start:start + best]

def contains_cycle(grid: list[list[str]]) -> bool:
    m, n = len(grid), len(grid[0])
    parent = list(range(m * n))

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]    # path halving
            x = parent[x]
        return x

    for r in range(m):
        row = grid[r]
        for c in range(n):
            ch = row[c]
            cell = r * n + c
            # Each same letter edge is added once: to the right and downward.
            if c + 1 < n and row[c + 1] == ch:
                a, b = find(cell), find(cell + 1)
                if a == b:
                    return True
                parent[a] = b
            if r + 1 < m and grid[r + 1][c] == ch:
                a, b = find(cell), find(cell + n)
                if a == b:
                    return True
                parent[a] = b
    return False

