def shifting_letters(s: str, shifts: list[list[int]]) -> str:
    n = len(s)
    diff = [0] * (n + 1)
    for start, end, direction in shifts:
        v = 1 if direction == 1 else -1
        diff[start] += v
        diff[end + 1] -= v
    out = []
