def cherry_pickup(grid: list[list[int]]) -> int:
    rows, cols = len(grid), len(grid[0])
    UNREACHABLE = -1
    dp = [[UNREACHABLE] * cols for _ in range(cols)]
    dp[0][cols - 1] = grid[0][0] + grid[0][cols - 1]
    for r in range(1, rows):
        row = grid[r]
        nxt = [[UNREACHABLE] * cols for _ in range(cols)]
        for a in range(cols):
            prev_rows = dp[max(0, a - 1):a + 2]
            for b in range(cols):
                lo, hi = max(0, b - 1), b + 2
                best = UNREACHABLE
                for prev in prev_rows:
                    m = max(prev[lo:hi])
                    if m > best:
                        best = m
                if best != UNREACHABLE:
                    gain = row[a] if a == b else row[a] + row[b]
                    nxt[a][b] = best + gain
        dp = nxt
    return max(max(line) for line in dp)

