def judge_point24(cards: list[int]) -> bool:
    EPS = 1e-6

    def solve(values: list[float]) -> bool:
        if len(values) == 1:
            return abs(values[0] - 24) < EPS
        for i in range(len(values)):
            for j in range(i + 1, len(values)):
                a, b = values[i], values[j]
                rest = [values[k] for k in range(len(values)) if k != i and k != j]
                results = [a + b, a * b, a - b, b - a]
