def split_array_same_average(nums: list[int]) -> bool:
    n, total = len(nums), sum(nums)
    half = n // 2
    sizes = [k for k in range(1, half + 1) if total * k % n == 0]
    if not sizes:
        return False
    # reach[k] has bit s set when some k items sum to s.
    reach = [0] * (half + 1)
    reach[0] = 1
    for count, x in enumerate(nums):
        for k in range(min(count, half - 1), -1, -1):
            if reach[k]:
                reach[k + 1] |= reach[k] << x
    return any(reach[k] >> (total * k // n) & 1 for k in sizes)

class MyHashSet:
    BUCKETS = 10007  # a prime, roughly the maximum number of keys

    def __init__(self):
        self.buckets = [[] for _ in range(self.BUCKETS)]

    def _bucket(self, key: int) -> list:
        return self.buckets[key % self.BUCKETS]

    def add(self, key: int) -> None:
        bucket = self._bucket(key)
        if key not in bucket:
            bucket.append(key)

    def remove(self, key: int) -> None:
        bucket = self._bucket(key)
        if key in bucket:
            bucket.remove(key)

    def contains(self, key: int) -> bool:
        return key in self._bucket(key)

