    health = list(healths)
    order = sorted(range(len(positions)), key=positions.__getitem__)
    right_movers = []  # stack of indices moving right, nearest on top
    for i in order:
        if directions[i] == "R":
            right_movers.append(i)
            continue
        # Robot i moves left and fights the nearest right movers.
        while right_movers and health[i] > 0:
            j = right_movers[-1]
            if health[j] < health[i]:
                health[j] = 0
                right_movers.pop()
                health[i] -= 1
            elif health[j] > health[i]:
                health[i] = 0
                health[j] -= 1
            else:
                health[i] = health[j] = 0
                right_movers.pop()
    return [h for h in health if h > 0]

