def number_ways(hats: list[list[int]]) -> int:
    MOD = 10**9 + 7
    n = len(hats)
    fans = [[] for _ in range(41)]  # hat -> people who like it
    for person, liked in enumerate(hats):
        for hat in liked:
            fans[hat].append(person)
    full = (1 << n) - 1
    dp = [0] * (full + 1)
    dp[0] = 1
    for hat in range(1, 41):
        if not fans[hat]:
            continue
        # Descending order: each hat goes to at most one person.
        for mask in range(full, -1, -1):
            ways = dp[mask]
            if not ways:
                continue
            for person in fans[hat]:
                bit = 1 << person
                if not mask & bit:
                    dp[mask | bit] = (dp[mask | bit] + ways) % MOD
    return dp[full]

