def word_pattern_match(pattern: str, s: str) -> bool:
    char_to_word = {}
    used = set()

    def place(pi: int, si: int) -> bool:
        if pi == len(pattern):
            return si == len(s)
        # every remaining pattern letter needs at least one character
        if len(s) - si < len(pattern) - pi:
            return False
        ch = pattern[pi]
        if ch in char_to_word:
            word = char_to_word[ch]
            return s.startswith(word, si) and place(pi + 1, si + len(word))
        # leave at least one character for each later pattern letter
        last_end = len(s) - (len(pattern) - pi - 1)
        for end in range(si + 1, last_end + 1):
            word = s[si:end]
            if word in used:
                continue
            char_to_word[ch] = word
            used.add(word)
            if place(pi + 1, end):
                return True
            del char_to_word[ch]
            used.discard(word)
        return False

    return place(0, 0)

