def valid_subarray_size(nums: List[int], threshold: int) -> int:
    n = len(nums)
    left = [-1] * n     # nearest index to the left with a smaller value
    right = [n] * n     # nearest index to the right with a smaller value
    stack = []
    for i, v in enumerate(nums):
        while stack and nums[stack[-1]] > v:
            right[stack.pop()] = i
        stack.append(i)
    stack = []
    for i in range(n - 1, -1, -1):
        v = nums[i]
        while stack and nums[stack[-1]] > v:
            left[stack.pop()] = i
        stack.append(i)
    for i, v in enumerate(nums):
        width = right[i] - left[i] - 1     # widest window where nums[i] is the minimum
        if v * width > threshold:
