def maximum_or(nums: List[int], k: int) -> int:
    n = len(nums)
    suffix = [0] * (n + 1)          # suffix[i] = OR of nums[i:]
    for i in range(n - 1, -1, -1):
        suffix[i] = suffix[i + 1] | nums[i]
    best = prefix = 0
    for i, value in enumerate(nums):
        # spend every doubling on nums[i], keep the rest unchanged
        candidate = prefix | (value << k) | suffix[i + 1]
        if candidate > best:
            best = candidate
        prefix |= value
    return best

