def count_pairs(deliciousness: List[int]) -> int:
    MOD = 10**9 + 7
    counts = Counter(deliciousness)
    total = 0
    for value, c in counts.items():
        for power in range(22):        # sums range up to 2^21
            partner = (1 << power) - value
            if partner < value:
                continue                # that pair is counted from the smaller value
            if partner == value:
                total += c * (c - 1) // 2
            elif partner in counts:
                total += c * counts[partner]
    return total % MOD

