def reverse_str(s: str, k: int) -> str:
    chars = list(s)
    for start in range(0, len(chars), 2 * k):
        # reverse the first k characters of this 2k block (fewer if the block is short)
        chars[start:start + k] = chars[start:start + k][::-1]
