def task_scheduler_ii(tasks: List[int], space: int) -> int:
    last_done = {}                # task type -> day it was last completed
    day = 0
    for task in tasks:
        day += 1
        if task in last_done:
            earliest = last_done[task] + space + 1
            if day < earliest:
                day = earliest    # take breaks until the cooldown is over
        last_done[task] = day
    return day

